<template>
  <div class="space-y-6">
    <div class="payment-tabs" role="tablist">
      <button v-for="tab in tabs" :key="tab.id" type="button" role="tab" :aria-selected="activeTab === tab.id" class="payment-tab" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">
        <component :is="tab.icon" :size="15" stroke-width="1.8" />
        <span>{{ tab.label }}</span>
      </button>
    </div>
    <div v-if="loading" class="flex justify-center py-20"><AppSpinner /></div>
    <div v-else-if="errorMessage" class="rounded-lg border border-error-30 bg-error-10 p-4 text-sm text-error">{{ errorMessage }}</div>

    <section v-else-if="activeTab === 'dashboard'" class="payment-dashboard">
      <div class="dashboard-toolbar"><div class="range-switch"><button v-for="range in [7, 30, 90]" :key="range" type="button" :class="{ active: dashboardDays === range }" @click="dashboardDays = range; loadDashboard()">{{ range }}天</button></div><button type="button" class="refresh-button" :disabled="dashboardLoading" title="刷新" @click="loadDashboard"><RefreshCw :size="16" :class="{ 'animate-spin': dashboardLoading }" /></button></div>
      <div class="stats-grid"><div class="stat-card"><span class="stat-icon green"><DollarSign :size="18" /></span><div><small>今日收入</small><b>{{ moneyAmount(dashboard.todayAmount, dashboardCurrency) }}</b><em>{{ dashboard.todayCount || 0 }} 订单</em></div></div><div class="stat-card"><span class="stat-icon blue"><CreditCard :size="18" /></span><div><small>总收入</small><b>{{ moneyAmount(dashboard.totalAmount, dashboardCurrency) }}</b><em>{{ dashboard.orderCount || 0 }} 订单</em></div></div><div class="stat-card"><span class="stat-icon purple"><BarChart3 :size="18" /></span><div><small>今日订单</small><b>{{ dashboard.todayCount || 0 }}</b></div></div><div class="stat-card"><span class="stat-icon amber"><BarChart3 :size="18" /></span><div><small>平均金额</small><b>{{ averageDashboardAmount }}</b></div></div></div>
      <div class="dashboard-panel revenue-panel"><h3>每日收入</h3><div v-if="dashboard.daily?.length" class="revenue-chart"><svg viewBox="0 0 1000 230" preserveAspectRatio="none" role="img" aria-label="每日收入图表"><line v-for="line in [40, 90, 140, 190]" :key="line" x1="0" :y1="line" x2="1000" :y2="line" class="chart-grid" /><polyline :points="revenuePoints" class="chart-line" /></svg><div class="chart-labels"><span v-for="item in dashboard.daily" :key="item.date">{{ item.date.slice(5) }}</span></div></div><div v-else class="chart-empty">暂无数据</div></div>
      <div class="dashboard-columns"><div class="dashboard-panel"><h3>支付方式分布</h3><div v-if="dashboard.paymentMethods?.length" class="distribution-list"><div v-for="item in dashboard.paymentMethods" :key="`${item.type}-${item.currency}`" class="distribution-row"><span><i :class="`method-dot ${item.type}`" />{{ methodLabel(item.type) }}</span><b>{{ moneyAmount(item.amount, item.currency) }} <small>({{ item.count }})</small></b></div></div><div v-else class="panel-empty">暂无数据</div></div><div class="dashboard-panel"><h3>消费排行</h3><div v-if="dashboard.topUsers?.length" class="leaderboard"><div v-for="(user, index) in dashboard.topUsers" :key="`${user.userId}-${user.currency}`"><span class="rank">{{ index + 1 }}</span><span class="user-name">{{ user.email || user.name }}</span><b>{{ moneyAmount(user.amount, user.currency) }}</b></div></div><div v-else class="panel-empty">暂无数据</div></div></div>
    </section>

    <form v-else-if="activeTab === 'settings'" class="payment-settings" @submit.prevent="saveSettings">
      <header class="settings-header">
        <div><h2>支付设置</h2><p>配置支付系统选项与用户端展示内容</p></div>
        <a href="https://github.com/Wei-Shaw/sub2api/blob/main/docs/PAYMENT_CN.md" class="guide-link" target="_blank" rel="noopener noreferrer">↗ 支付配置指南</a>
      </header>
      <section class="settings-section settings-enable">
        <div><h3>启用支付</h3><p>启用或禁用支付系统</p></div>
        <button type="button" class="switch" :class="{ active: settings.enabled }" :aria-pressed="settings.enabled" @click="settings.enabled = !settings.enabled"><span /></button>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>商品信息</h3><span>支付页面中显示的商品名称</span></div>
        <div class="settings-grid product-grid"><Field v-model="settings.productNamePrefix" label="商品名前缀" placeholder="VoiceHub 点歌券" /><div class="field"><span>货币类型</span><CustomSelect v-model="settings.currency" :options="currencyOptions" /></div><div class="field"><span>预览</span><div class="input preview">{{ settings.productNamePrefix || 'VoiceHub 点歌券' }}100 {{ settings.currency || 'CNY' }}</div></div></div>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>金额与订单</h3><span>金额单位均为分，留空表示不限制</span></div>
        <div class="settings-grid amount-grid"><Field v-model.number="settings.minAmountCents" type="number" min="1" label="最低金额" /><Field v-model.number="settings.maxAmountCents" type="number" min="1" label="最高金额" placeholder="不限制" /><Field v-model.number="settings.dailyLimitCents" type="number" min="1" label="每日限额" placeholder="不限制" /><Field v-model.number="settings.orderTimeoutMinutes" type="number" min="1" label="订单超时时间" /><Field v-model.number="settings.maxPendingOrders" type="number" min="1" label="最大待支付订单数" /><Field v-model.number="settings.balanceRechargeMultiplier" type="number" step="0.01" min="0.01" label="点歌券价值倍率" /><Field v-model.number="settings.subscriptionUsdToCnyRate" type="number" step="0.01" min="0" label="套餐 USD/CNY 汇率" placeholder="未启用" /><Field v-model.number="settings.rechargeFeeRate" type="number" step="0.01" min="0" max="100" label="支付手续费率" /></div>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>支付策略</h3><span>控制通道选择与订单行为</span></div>
        <div class="settings-grid strategy-grid"><div class="field"><span>负载均衡策略</span><CustomSelect v-model="settings.loadBalanceStrategy" :options="balanceOptions" /></div><div class="field"><span>限制取消频率</span><div class="inline-controls"><button type="button" class="switch small" :class="{ active: settings.cancelLimitEnabled }" :aria-pressed="settings.cancelLimitEnabled" @click="settings.cancelLimitEnabled = !settings.cancelLimitEnabled"><span /></button><CustomSelect v-model="settings.cancelWindowMode" :options="cancelModeOptions" :disabled="!settings.cancelLimitEnabled" class="compact-select" /><span class="muted">每</span><input v-model.number="settings.cancelWindowMinutes" class="input compact" type="number" min="1" :disabled="!settings.cancelLimitEnabled"><CustomSelect v-model="settings.cancelWindowUnit" :options="cancelUnitOptions" :disabled="!settings.cancelLimitEnabled" class="compact-select" /><span class="muted">最多</span><input v-model.number="settings.cancelMaxCount" class="input compact" type="number" min="1" :disabled="!settings.cancelLimitEnabled"><span class="muted">次</span></div></div></div>
        <label class="setting-toggle"><button type="button" class="switch small" :class="{ active: settings.alipayForceQrCode }" :aria-pressed="settings.alipayForceQrCode" @click="settings.alipayForceQrCode = !settings.alipayForceQrCode"><span /></button><span><b>支付宝强制二维码支付</b><small>移动端支付宝统一使用二维码，不跳转手机网站</small></span></label><label class="setting-toggle"><button type="button" class="switch small" :class="{ active: settings.alipayMobileDeepLink }" :aria-pressed="settings.alipayMobileDeepLink" @click="settings.alipayMobileDeepLink = !settings.alipayMobileDeepLink"><span /></button><span><b>支付宝移动端当面付唤起</b><small>移动端优先尝试打开支付宝客户端，失败时回退二维码</small></span></label>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>启用的支付服务商</h3><span>启用后，服务商支持的支付方式才会出现在用户支付页</span></div>
        <div v-if="providers.length" class="provider-enable-list"><label v-for="provider in providers" :key="provider.id" class="provider-enable-row" :class="{ selected: provider.enabled }"><span class="provider-enable-main"><button type="button" class="switch small" :class="{ active: provider.enabled }" :aria-pressed="provider.enabled" @click="provider.enabled = !provider.enabled"><span /></button><span><b>{{ provider.name }}</b><small>{{ provider.providerKey }} · {{ provider.supportedMethods.map(methodLabel).join(' / ') || '未配置支付方式' }}</small></span></span><span class="provider-state">{{ provider.enabled ? '已启用' : '已停用' }}</span></label></div><div v-else class="empty-provider">请先添加支付服务商</div>
      </section>
      <section id="payment-help" class="settings-section help-section"><div class="section-heading"><h3>帮助内容</h3><span>为用户提供支付说明</span></div><div class="help-grid"><div class="help-image"><span>帮助图片链接</span><input v-model="settings.helpImageUrl" class="input" placeholder="上传或输入图片链接"><div v-if="settings.helpImageUrl" class="help-preview"><img :src="settings.helpImageUrl" alt="帮助图片预览"></div></div><textarea v-model="settings.helpText" rows="5" class="input help-input" placeholder="输入帮助说明文本..." /></div></section>
      <section class="settings-section provider-inline"><div class="section-heading provider-heading"><div><h3>服务商管理</h3><span>可拖动调整优先级，服务商支持独立启用或禁用</span></div><button type="button" class="small-button" @click="editProvider()"><Plus :size="14" />添加服务商</button></div><div v-if="providers.length" class="provider-management-list"><article v-for="provider in providers" :key="provider.id" class="provider-management-row" :class="{ dragging: draggingProviderId === provider.id }" draggable="true" @dragstart="startProviderDrag(provider)" @dragover.prevent @drop="dropProvider(provider)"><button type="button" class="provider-drag-handle" title="拖动调整优先级" aria-label="拖动调整优先级"><GripVertical :size="18" /></button><div class="provider-main"><div class="provider-title"><b>{{ provider.name }}</b><span class="provider-type">{{ provider.providerKey }}</span><span class="provider-status" :class="{ enabled: provider.enabled }">{{ provider.enabled ? '已启用' : '已禁用' }}</span></div><div class="provider-method-tags"><span v-for="method in provider.supportedMethods" :key="method" class="provider-method-tag">{{ methodLabel(method) }}</span><span class="provider-order">优先级 {{ provider.sortOrder }}</span></div><small>退款：{{ provider.refundEnabled ? '支持' : '不支持' }} · 用户退款：{{ provider.allowUserRefund ? '允许' : '不允许' }}</small></div><div class="provider-actions"><button type="button" class="provider-switch" :class="{ active: provider.enabled }" :aria-pressed="provider.enabled" :title="provider.enabled ? '禁用服务商' : '启用服务商'" @click.stop="toggleProviderEnabled(provider)"><span /></button><button type="button" class="provider-switch refund-switch" :class="{ active: provider.refundEnabled }" :aria-pressed="provider.refundEnabled" :title="provider.refundEnabled ? '关闭退款' : '启用退款'" @click.stop="toggleProviderRefund(provider)"><span /></button><button type="button" class="small-button" title="编辑" @click.stop="editProvider(provider)"><Pencil :size="14" /></button><button type="button" class="small-button danger-button" title="删除" @click.stop="removeProvider(provider)"><Trash2 :size="14" /></button></div></article></div><div v-else class="empty-provider">暂未配置支付服务商</div></section>
      <footer class="settings-footer"><span>修改后保存即可立即生效</span><button class="primary-button" :disabled="saving"><Save :size="16" />{{ locale.admin.save }}</button></footer>
    </form>

    <section v-else-if="activeTab === 'providers'" class="space-y-4">
      <div class="flex justify-end"><button class="primary-button" @click="editProvider()"><Plus :size="16" />{{ locale.admin.add }}</button></div>
      <div class="grid gap-4 lg:grid-cols-2"><article v-for="provider in providers" :key="provider.id" class="rounded-lg border border-border-secondary bg-bg-secondary p-5"><div class="flex items-start justify-between gap-3"><div><h3 class="font-black">{{ provider.name }}</h3><p class="text-xs uppercase text-text-tertiary">{{ provider.providerKey }}</p></div><span :class="provider.enabled ? 'text-success' : 'text-text-disabled'">{{ provider.enabled ? 'ON' : 'OFF' }}</span></div><p class="mt-3 text-sm text-text-tertiary">{{ provider.supportedMethods.map(methodLabel).join(' / ') }}</p><div class="mt-4 flex gap-2"><button class="small-button" @click="editProvider(provider)"><Pencil :size="14" />编辑</button><button class="small-button text-error" @click="removeProvider(provider)"><Trash2 :size="14" />删除</button></div></article></div>
    </section>

    <section v-else-if="activeTab === 'plans'" class="space-y-4">
      <div class="flex justify-end"><button class="primary-button" @click="editPlan()"><Plus :size="16" />{{ locale.admin.add }}</button></div>
      <div class="overflow-x-auto rounded-lg border border-border-secondary"><table class="w-full text-left text-sm"><thead class="bg-bg-secondary text-text-tertiary"><tr><th class="p-3">名称</th><th class="p-3">价格</th><th class="p-3">点歌券</th><th class="p-3">状态</th><th class="p-3"></th></tr></thead><tbody><tr v-for="plan in plans" :key="plan.id" class="border-t border-border-secondary"><td class="p-3 font-bold">{{ plan.name }}</td><td class="p-3">{{ money(plan.priceCents, plan.currency) }}</td><td class="p-3">{{ plan.cardCount }}</td><td class="p-3">{{ plan.forSale ? '在售' : '下架' }}</td><td class="p-3"><div class="flex gap-2"><button class="small-button" @click="editPlan(plan)"><Pencil :size="14" /></button><button class="small-button text-error" @click="removePlan(plan)"><Trash2 :size="14" /></button></div></td></tr></tbody></table></div>
    </section>

    <section v-else class="orders-page">
      <div class="orders-filters"><div class="search-box"><Search :size="16" /><input v-model="orderFilters.keyword" placeholder="搜索订单..." @keyup.enter="resetAndLoadOrders"></div><CustomSelect v-model="orderFilters.status" :options="statusOptions" class="filter-select" @update:model-value="resetAndLoadOrders" /><CustomSelect v-model="orderFilters.method" :options="methodFilterOptions" class="filter-select" @update:model-value="resetAndLoadOrders" /><button type="button" class="refresh-button order-refresh" :disabled="ordersLoading" title="刷新" @click="loadOrders"><RefreshCw :size="16" :class="{ 'animate-spin': ordersLoading }" /></button></div>
      <div class="orders-table-wrap"><table class="orders-table"><thead><tr><th>订单 ID</th><th>订单编号</th><th>用户</th><th>实付</th><th>支付方式</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="(order, index) in orders" :key="order.id"><td>#{{ (orderFilters.page - 1) * orderFilters.pageSize + index + 1 }}</td><td class="order-number">{{ order.outTradeNo }}</td><td>{{ order.userEmail || order.userName }}</td><td>{{ money(order.payAmountCents, order.currency) }}</td><td>{{ methodLabel(order.paymentMethod) }}</td><td><span class="status-badge" :class="statusClass(order.status)">{{ statusLabel(order.status) }}</span></td><td class="order-time">{{ formatDateTime(order.createdAt) }}</td><td><div class="order-actions"><button type="button" @click="showOrderDetail(order)"><Eye :size="14" />查看</button><button v-if="['PENDING','PAID','FAILED','EXPIRED'].includes(order.status)" type="button" class="retry" @click="verifyOrder(order)"><RefreshCw :size="14" />重试</button><button v-if="['COMPLETED','REFUND_REQUESTED'].includes(order.status)" type="button" class="refund" @click="openRefund(order)"><Undo2 :size="14" />退款</button></div></td></tr><tr v-if="!orders.length"><td colspan="8" class="orders-empty">暂无订单</td></tr></tbody></table></div>
      <div class="orders-pagination"><span>显示 {{ orderTotal ? (orderFilters.page - 1) * orderFilters.pageSize + 1 : 0 }} 至 {{ Math.min(orderFilters.page * orderFilters.pageSize, orderTotal) }} 共 {{ orderTotal }} 条结果</span><div class="page-size">每页：<CustomSelect v-model="orderFilters.pageSize" :options="pageSizeOptions" @update:model-value="resetAndLoadOrders" /></div><div class="page-buttons"><button type="button" :disabled="orderFilters.page <= 1" @click="changeOrderPage(orderFilters.page - 1)">‹</button><span>{{ orderFilters.page }}</span><button type="button" :disabled="orderFilters.page >= orderPageCount" @click="changeOrderPage(orderFilters.page + 1)">›</button></div></div>
    </section>

    <Teleport to="body">
      <div v-if="providerDraft" class="modal" @click.self="providerDraft = null"><form class="dialog provider-dialog" @submit.prevent="saveProvider"><div class="dialog-title"><div><h2>{{ providerDraft.id ? '编辑支付服务商' : '添加支付服务商' }}</h2><p class="dialog-subtitle">配置密钥、通道和回调参数后即可启用。</p></div><button type="button" class="dialog-close" @click="providerDraft = null">×</button></div><div class="grid gap-4 sm:grid-cols-2"><div><label>服务商类型</label><CustomSelect v-model="providerDraft.providerKey" :options="providerOptions" :disabled="!!providerDraft.id" /></div><Field v-model="providerDraft.name" label="服务商名称" placeholder="例如：主支付通道" /><Field v-model.number="providerDraft.sortOrder" type="number" label="排序" min="0" /></div><div class="provider-options"><label class="check"><input v-model="providerDraft.enabled" type="checkbox" />启用服务商</label><label class="check"><input v-model="providerDraft.refundEnabled" type="checkbox" />允许退款</label><label class="check" :class="{ disabled: !providerDraft.refundEnabled }"><input v-model="providerDraft.allowUserRefund" type="checkbox" :disabled="!providerDraft.refundEnabled" />允许用户申请退款</label></div><div v-if="providerDraft.providerKey === 'easypay' || providerDraft.providerKey === 'alipay'" class="provider-section"><div class="section-title">支付模式</div><div class="segmented"><button v-for="mode in paymentModes" :key="mode.value" type="button" :class="{ active: providerDraft.paymentMode === mode.value }" @click="providerDraft.paymentMode = mode.value">{{ mode.label }}</button></div></div><div class="provider-section"><div class="section-title">支持的支付方式</div><div class="method-list"><label v-for="method in providerMethods" :key="method" class="method-chip" :class="{ selected: providerDraft.supportedMethods.includes(method) }"><input v-model="providerDraft.supportedMethods" type="checkbox" :value="method" />{{ methodLabel(method) }}</label></div></div><div v-if="providerDraft.providerKey === 'easypay'" class="provider-section"><div class="section-title">易支付自定义渠道</div><div class="grid gap-3 sm:grid-cols-3"><Field v-model="providerDraft.config.cid" label="通用渠道 ID" placeholder="可选" /><Field v-model="providerDraft.config.cidAlipay" label="支付宝渠道 ID" placeholder="可选" /><Field v-model="providerDraft.config.cidWxpay" label="微信渠道 ID" placeholder="可选" /></div><p class="field-hint">留空时使用服务商默认渠道；支付模式可在上方切换为二维码或弹窗。</p></div><div class="provider-section"><div class="section-title">服务商参数</div><div class="grid gap-4 sm:grid-cols-2"><label v-for="field in providerFields" :key="field.key" class="field"><span>{{ field.label }}<em v-if="field.optional">（可选）</em><i v-else> *</i></span><div class="relative"><textarea v-if="field.textarea" v-model="providerDraft.config[field.key]" class="input w-full font-mono text-xs" rows="4" :placeholder="fieldPlaceholder(field)" /><CustomSelect v-else-if="field.options" v-model="providerDraft.config[field.key]" :options="field.options" /><input v-else v-model="providerDraft.config[field.key]" class="input w-full" :type="field.sensitive && !providerVisible[field.key] ? 'password' : 'text'" :placeholder="fieldPlaceholder(field)" autocomplete="new-password" data-1p-ignore /></div><small v-if="field.hint">{{ field.hint }}</small><button v-if="field.sensitive" type="button" class="secret-toggle" :title="providerVisible[field.key] ? '隐藏' : '显示'" @click="providerVisible[field.key] = !providerVisible[field.key]"><Eye v-if="!providerVisible[field.key]" :size="15" /><EyeOff v-else :size="15" /></button></label></div></div><div class="provider-section"><div class="section-title">回调地址</div><div class="callback-list"><div><span>异步通知地址</span><code>{{ callbackUrl(providerDraft.providerKey) }}</code></div><div><span>同步跳转地址</span><code>{{ returnUrl }}</code></div></div><p class="field-hint">请将异步通知地址配置到对应支付服务商后台，支付完成后系统会自动更新订单。</p></div><div class="provider-section"><div class="section-title">按支付方式限额（元）</div><div v-for="method in providerMethods" :key="method" class="limit-row"><b>{{ methodLabel(method) }}</b><Field v-model.number="providerDraft.limits[method].singleMin" type="number" min="0" step="0.01" label="单笔最低" placeholder="不限制" /><Field v-model.number="providerDraft.limits[method].singleMax" type="number" min="0" step="0.01" label="单笔最高" placeholder="不限制" /><Field v-model.number="providerDraft.limits[method].dailyLimit" type="number" min="0" step="0.01" label="每日限额" placeholder="不限制" /></div><p class="field-hint">留空或填 0 表示不限制；限额只影响当前服务商，不改变全局支付设置。</p></div><div class="dialog-actions"><button type="button" class="small-button" @click="providerDraft = null">取消</button><button class="primary-button" :disabled="providerSaving">{{ providerSaving ? '保存中…' : '保存服务商' }}</button></div></form></div>
      <div v-if="planDraft" class="modal" @click.self="planDraft = null"><form class="dialog" @submit.prevent="savePlan"><h2>点歌券套餐</h2><Field v-model="planDraft.name" label="名称" /><Field v-model="planDraft.description" label="说明" /><div class="grid grid-cols-2 gap-4"><Field v-model.number="planDraft.priceYuan" type="number" min="0.01" step="0.01" label="价格（元）" /><Field v-model.number="planDraft.cardCount" type="number" min="1" label="点歌券数量" /></div><label class="check"><input v-model="planDraft.forSale" type="checkbox" />在售</label><div class="dialog-actions"><button type="button" class="small-button" @click="planDraft = null">取消</button><button class="primary-button">保存</button></div></form></div>
      <div v-if="refundDraft" class="modal" @click.self="refundDraft = null"><form class="dialog" @submit.prevent="refundOrder"><h2>订单退款</h2><Field v-model.number="refundDraft.amountCents" type="number" label="退款金额（分）" /><Field v-model="refundDraft.reason" label="原因" /><div class="dialog-actions"><button type="button" class="small-button" @click="refundDraft = null">取消</button><button class="primary-button">退款</button></div></form></div>
      <div v-if="selectedOrder" class="modal" @click.self="selectedOrder = null"><div class="dialog order-detail-dialog"><div class="dialog-title"><h2>订单详情</h2><button type="button" @click="selectedOrder = null">×</button></div><div class="detail-grid"><div><small>订单 ID</small><b>{{ selectedOrder.id }}</b></div><div><small>订单编号</small><b>{{ selectedOrder.outTradeNo }}</b></div><div><small>状态</small><span class="status-badge" :class="statusClass(selectedOrder.status)">{{ statusLabel(selectedOrder.status) }}</span></div><div><small>实付金额</small><b>{{ money(selectedOrder.payAmountCents, selectedOrder.currency) }}</b></div><div><small>用户</small><b>{{ selectedOrder.userEmail || selectedOrder.userName }}</b></div><div><small>支付方式</small><b>{{ methodLabel(selectedOrder.paymentMethod) }}</b></div><div><small>创建时间</small><b>{{ formatDateTime(selectedOrder.createdAt) }}</b></div><div><small>过期时间</small><b>{{ formatDateTime(selectedOrder.expiresAt) }}</b></div></div><div v-if="selectedAuditLogs.length" class="audit-list"><h3>审计日志</h3><div v-for="log in selectedAuditLogs" :key="log.id"><b>{{ log.action }}</b><span>{{ formatDateTime(log.createdAt) }}</span></div></div></div></div>
    </Teleport>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref, toRaw, watch } from 'vue'
import { BarChart3, ClipboardList, CreditCard, DollarSign, Eye, EyeOff, GripVertical, Package, Pencil, Plus, RefreshCw, Save, Search, Trash2, Undo2 } from '@lucide/vue'
import AppSpinner from '~/components/UI/Common/AppSpinner.vue'; import CustomSelect from '~/components/UI/Common/CustomSelect.vue'; import { useLocale } from '~/utils/locale'; import { useServerErrors } from '~/composables/useLocaleText'; import { useToast } from '~/composables/useToast'
const Field = defineComponent({ props: { modelValue: [String, Number], label: String, placeholder: String, step: [String, Number], min: [String, Number], max: [String, Number], type: { type: String, default: 'text' } }, emits: ['update:modelValue'], setup(props, { emit }) { return () => h('label', { class: 'field' }, [h('span', props.label), h('input', { class: 'input w-full', value: props.modelValue ?? '', placeholder: props.placeholder, step: props.step, min: props.min, max: props.max, type: props.type, onInput: event => emit('update:modelValue', props.type === 'number' ? Number(event.target.value) : event.target.value) })]) } })
const sections = useLocale(); const locale = computed(() => sections.payment.value); const { localize } = useServerErrors(); const { showToast } = useToast(); const activeTab = ref('dashboard'); const loading = ref(true); const saving = ref(false); const errorMessage = ref('')
const settings = ref({ visibleMethods: [] }); const providers = ref([]); const plans = ref([]); const orders = ref([]); const dashboard = ref({}); const dashboardDays = ref(30); const dashboardLoading = ref(false); const providerDraft = ref(null); const providerVisible = ref({}); const providerSaving = ref(false); const planDraft = ref(null); const refundDraft = ref(null); const orderFilters = ref({ keyword: '', status: '', method: '', page: 1, pageSize: 20 }); const orderTotal = ref(0); const ordersLoading = ref(false); const selectedOrder = ref(null); const selectedAuditLogs = ref([]); const loadedTabs = ref({ dashboard: false, orders: false, plans: false }); const draggingProviderId = ref(null)
const tabIcons = { dashboard: BarChart3, orders: ClipboardList, plans: Package, settings: CreditCard }
const tabs = computed(() => ['dashboard', 'orders', 'plans', 'settings'].map(id => ({ id, label: locale.value.admin[id], icon: tabIcons[id] })))
const methods = ['alipay','wxpay','stripe','airwallex']; const methodLabel = value => ({ alipay: '支付宝', wxpay: '微信支付', stripe: 'Stripe', airwallex: 'Airwallex' }[value] || value)
const currencyOptions = [{ value: 'CNY', label: 'CNY（人民币）' }, { value: 'USD', label: 'USD（美元）' }]
const enabledProviderMethods = computed(() => [...new Set(providers.value.filter(provider => provider.enabled).flatMap(provider => provider.supportedMethods || []))])
const providerOptions = [{ value: 'easypay', label: 'EasyPay' }, { value: 'alipay', label: '支付宝官方' }, { value: 'wxpay', label: '微信支付官方' }, { value: 'stripe', label: 'Stripe' }, { value: 'airwallex', label: 'Airwallex' }]
const providerMethodsMap = { easypay: ['alipay','wxpay'], alipay: ['alipay'], wxpay: ['wxpay'], stripe: ['stripe'], airwallex: ['airwallex'] }
const providerMethods = computed(() => providerMethodsMap[providerDraft.value?.providerKey] || [])
const paymentCurrencyOptions = ['CNY','HKD','USD','EUR','GBP','AUD','CAD','SGD','JPY','KRW','NZD'].map(value => ({ value, label: value }))
const providerFieldMap = {
  easypay: [
    { key:'pid', label:'商户 PID' },
    { key:'pkey', label:'商户密钥 PKey', sensitive:true },
    { key:'apiBase', label:'API 基础地址', placeholder:'https://pay.example.com', hint:'填写易支付站点地址，无需附加 submit.php。' }
  ],
  alipay: [
    { key:'appId', label:'应用 App ID' },
    { key:'privateKey', label:'应用私钥', sensitive:true, textarea:true, placeholder:'-----BEGIN PRIVATE KEY-----' },
    { key:'publicKey', label:'支付宝公钥', sensitive:true, textarea:true, placeholder:'-----BEGIN PUBLIC KEY-----' },
    { key:'gateway', label:'支付宝网关', optional:true, placeholder:'https://openapi.alipay.com/gateway.do', hint:'不填写时使用支付宝正式环境网关。' }
  ],
  wxpay: [
    { key:'appId', label:'应用 App ID' },
    { key:'mchId', label:'商户号' },
    { key:'privateKey', label:'商户 API 私钥', sensitive:true, textarea:true, placeholder:'-----BEGIN PRIVATE KEY-----' },
    { key:'apiV3Key', label:'API v3 密钥', sensitive:true },
    { key:'publicKey', label:'微信支付公钥', sensitive:true, textarea:true, placeholder:'-----BEGIN PUBLIC KEY-----' },
    { key:'publicKeyId', label:'微信支付公钥 ID' },
    { key:'serialNo', label:'商户证书序列号' },
    { key:'refundNotifyUrl', label:'退款通知地址', optional:true, placeholder:'https://your-domain/api/payment/refund-notify', hint:'未配置独立退款通知接口时可留空。' }
  ],
  stripe: [
    { key:'secretKey', label:'Secret Key', sensitive:true, placeholder:'sk_live_...' },
    { key:'publishableKey', label:'Publishable Key', placeholder:'pk_live_...' },
    { key:'webhookSecret', label:'Webhook Secret', sensitive:true, placeholder:'whsec_...' },
    { key:'currency', label:'支付币种', options:paymentCurrencyOptions, defaultValue:'CNY', hint:'币种需与 Stripe 账户和套餐币种保持一致。' }
  ],
  airwallex: [
    { key:'clientId', label:'Client ID' },
    { key:'apiKey', label:'API Key', sensitive:true },
    { key:'webhookSecret', label:'Webhook Secret', sensitive:true },
    { key:'apiBase', label:'API 基础地址', defaultValue:'https://api.airwallex.com/api/v1', hint:'测试密钥应使用 https://api-demo.airwallex.com/api/v1。' },
    { key:'countryCode', label:'国家/地区代码', defaultValue:'CN', placeholder:'CN' },
    { key:'currency', label:'支付币种', options:paymentCurrencyOptions, defaultValue:'CNY' },
    { key:'accountId', label:'Airwallex 账户 ID', optional:true, hint:'单账户 Scoped API Key 通常无需填写。' }
  ]
}
const providerFields = computed(() => providerFieldMap[providerDraft.value?.providerKey] || [])
const paymentModes = computed(() => providerDraft.value?.providerKey === 'alipay'
  ? [{ value:'', label:'二维码' }, { value:'redirect', label:'跳转' }]
  : [{ value:'qrcode', label:'二维码' }, { value:'popup', label:'弹窗' }])
const siteOrigin = ref('')
const callbackUrl = providerKey => `${siteOrigin.value}/api/payment/webhook/${providerKey}`
const returnUrl = computed(() => `${siteOrigin.value}/payment/result`)
const fieldPlaceholder = field => providerDraft.value?.id && field.sensitive ? '已配置，输入新值可替换' : (field.placeholder || field.defaultValue || '')
const balanceOptions = [{ value: 'round-robin', label: '轮询' }, { value: 'least-amount', label: '最少金额' }]
const cancelModeOptions = [{ value: 'rolling', label: '滚动窗口' }, { value: 'fixed', label: '固定窗口' }]
const cancelUnitOptions = [{ value: 'minute', label: '分钟' }, { value: 'hour', label: '小时' }, { value: 'day', label: '天' }]
const statusOptions = [{ value:'',label:'全部状态' },{ value:'PENDING',label:'待支付' },{ value:'PAID',label:'已支付' },{ value:'COMPLETED',label:'已完成' },{ value:'EXPIRED',label:'已过期' },{ value:'CANCELLED',label:'已取消' },{ value:'FAILED',label:'失败' },{ value:'REFUND_REQUESTED',label:'申请退款' },{ value:'REFUNDING',label:'退款中' },{ value:'REFUNDED',label:'已退款' }]
const methodFilterOptions = [{ value: '', label: '全部支付方式' }, ...methods.map(value => ({ value, label: methodLabel(value) }))]
const pageSizeOptions = [10, 20, 50, 100].map(value => ({ value, label: String(value) }))
const orderPageCount = computed(() => Math.max(1, Math.ceil(orderTotal.value / Number(orderFilters.value.pageSize || 20))))
const money = (cents, currency = 'CNY') => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cents / 100)
const moneyAmount = (amount = 0, currency = 'CNY') => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(Number(amount || 0))
const dashboardCurrency = computed(() => dashboard.value.paymentMethods?.[0]?.currency || settings.value.currency || 'CNY')
const averageDashboardAmount = computed(() => moneyAmount(dashboard.value.avgAmount?.[dashboardCurrency.value] || 0, dashboardCurrency.value))
const revenuePoints = computed(() => { const rows = dashboard.value.daily || []; const values = rows.map(item => Number(item.amount?.[dashboardCurrency.value] || 0)); const max = Math.max(1, ...values); return values.map((value, index) => `${rows.length === 1 ? 500 : index * 1000 / (rows.length - 1)},${210 - value / max * 180}`).join(' ') })
const api = async (url, options) => { try { return await $fetch(url, options) } catch (error) { errorMessage.value = localize(error); throw error } }
const loadDashboard = async () => { dashboardLoading.value = true; try { dashboard.value = await api('/api/admin/payment/dashboard', { query: { days: dashboardDays.value } }) } finally { dashboardLoading.value = false } }
const loadOrders = async () => { ordersLoading.value = true; try { const result = await api('/api/admin/payment/orders', { query: orderFilters.value }); orders.value = result.items; orderTotal.value = result.total; loadedTabs.value.orders = true } finally { ordersLoading.value = false } }
const loadPlans = async () => { plans.value = await api('/api/admin/payment/plans'); loadedTabs.value.plans = true }
const resetAndLoadOrders = () => { orderFilters.value.page = 1; loadOrders() }
const changeOrderPage = page => { orderFilters.value.page = page; loadOrders() }
const formatDateTime = value => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'short', timeStyle: 'medium' }).format(new Date(value)) : '-'
const statusLabel = status => ({ PENDING:'待支付',PAID:'已支付',COMPLETED:'已完成',EXPIRED:'已过期',CANCELLED:'已取消',FAILED:'失败',REFUND_REQUESTED:'申请退款',REFUNDING:'退款中',REFUNDED:'已退款' }[status] || status)
const statusClass = status => ({ PENDING:'pending',PAID:'paid',COMPLETED:'completed',EXPIRED:'neutral',CANCELLED:'neutral',FAILED:'failed',REFUND_REQUESTED:'refund',REFUNDING:'refund',REFUNDED:'refunded' }[status] || 'neutral')
const showOrderDetail = async order => { selectedOrder.value = order; selectedAuditLogs.value = []; try { const result = await api(`/api/admin/payment/orders/${order.id}`); selectedOrder.value = result.order; selectedAuditLogs.value = result.auditLogs || [] } catch {} }
const loadCore = async () => {
  loading.value = true
  errorMessage.value = ''
  try {
    const results = await Promise.allSettled([
      $fetch('/api/admin/payment/settings'),
      $fetch('/api/admin/payment/providers')
    ])
    const [settingsResult, providersResult] = results
    if (settingsResult.status === 'fulfilled') settings.value = settingsResult.value
    if (providersResult.status === 'fulfilled') providers.value = providersResult.value
    if (results.every(result => result.status === 'rejected')) errorMessage.value = localize(results[0].reason)
  } finally {
    loading.value = false
  }
}
const ensureActiveTabLoaded = async tab => {
  if (tab === 'dashboard' && !loadedTabs.value.dashboard) { await loadDashboard(); loadedTabs.value.dashboard = true }
  if (tab === 'orders' && !loadedTabs.value.orders) await loadOrders()
  if (tab === 'plans' && !loadedTabs.value.plans) await loadPlans()
}
watch(activeTab, tab => { ensureActiveTabLoaded(tab) })
const saveSettings = async () => { saving.value=true; try { const visibleMethods = enabledProviderMethods.value; settings.value = await api('/api/admin/payment/settings', { method:'PUT', body:{ ...settings.value, currency: settings.value.currency || 'CNY', productNameSuffix: settings.value.currency || 'CNY', minAmountCents: Number(settings.value.minAmountCents) || 1, maxPendingOrders: Number(settings.value.maxPendingOrders) || 3, visibleMethods } }); await Promise.all(providers.value.map(provider => api(`/api/admin/payment/providers/${provider.id}`, { method:'PUT', body: provider }))); showToast('支付设置保存成功', 'success') } finally { saving.value=false } }
const persistProvider = provider => api(`/api/admin/payment/providers/${provider.id}`, { method: 'PUT', body: provider })
const toggleProviderEnabled = async provider => { const previous = provider.enabled; provider.enabled = !previous; try { await persistProvider(provider); showToast(provider.enabled ? '服务商已启用' : '服务商已禁用', 'success') } catch { provider.enabled = previous } }
const toggleProviderRefund = async provider => { const previous = provider.refundEnabled; const previousUserRefund = provider.allowUserRefund; provider.refundEnabled = !previous; if (!provider.refundEnabled) provider.allowUserRefund = false; try { await persistProvider(provider); showToast(provider.refundEnabled ? '退款功能已启用' : '退款功能已禁用', 'success') } catch { provider.refundEnabled = previous; provider.allowUserRefund = previousUserRefund } }
const startProviderDrag = provider => { draggingProviderId.value = provider.id }
const dropProvider = async target => { const sourceId = draggingProviderId.value; draggingProviderId.value = null; if (!sourceId || sourceId === target.id) return; const sourceIndex = providers.value.findIndex(item => item.id === sourceId); const targetIndex = providers.value.findIndex(item => item.id === target.id); if (sourceIndex < 0 || targetIndex < 0) return; const next = [...providers.value]; const [moved] = next.splice(sourceIndex, 1); const insertIndex = sourceIndex < targetIndex ? targetIndex - 1 : targetIndex; next.splice(insertIndex, 0, moved); next.forEach((provider, index) => { provider.sortOrder = index * 10 }); providers.value = next; try { await Promise.all(next.map(persistProvider)); showToast('服务商优先级已更新', 'success') } catch { providers.value = await api('/api/admin/payment/providers') } }
const cloneData = value => JSON.parse(JSON.stringify(toRaw(value)))
const normalizeProviderLimits = (providerKey, source = {}) => {
  const result = {}
  for (const method of providerMethodsMap[providerKey] || []) {
    const current = source?.[method]
    if (current && typeof current === 'object') result[method] = { singleMin:current.singleMin || '', singleMax:current.singleMax || '', dailyLimit:current.dailyLimit || '' }
    else result[method] = {
      singleMin: source.minAmountCents ? Number(source.minAmountCents) / 100 : '',
      singleMax: source.maxAmountCents ? Number(source.maxAmountCents) / 100 : '',
      dailyLimit: source.dailyLimitCents ? Number(source.dailyLimitCents) / 100 : ''
    }
  }
  return result
}
const applyProviderDefaults = draft => {
  for (const field of providerFieldMap[draft.providerKey] || []) {
    if (field.defaultValue && !draft.config[field.key]) draft.config[field.key] = field.defaultValue
  }
}
const editProvider = provider => {
  const key = provider?.providerKey || 'easypay'
  const draft = provider ? cloneData(provider) : { providerKey:key, name:'', supportedMethods:[...(providerMethodsMap[key] || [])], enabled:true, sortOrder:0, refundEnabled:false, allowUserRefund:false, paymentMode:'qrcode' }
  draft.config = cloneData(provider?.config || {})
  draft.limits = normalizeProviderLimits(key, provider?.limits || {})
  applyProviderDefaults(draft)
  providerVisible.value = {}
  providerDraft.value = draft
}
watch(() => providerDraft.value?.providerKey, key => {
  if (!providerDraft.value || providerDraft.value.id) return
  providerDraft.value.supportedMethods = [...(providerMethodsMap[key] || [])]
  providerDraft.value.paymentMode = key === 'easypay' ? 'qrcode' : ''
  providerDraft.value.config = {}
  providerDraft.value.limits = normalizeProviderLimits(key)
  applyProviderDefaults(providerDraft.value)
})
watch(() => providerDraft.value?.refundEnabled, enabled => { if (providerDraft.value && !enabled) providerDraft.value.allowUserRefund = false })
const cleanProviderLimits = limits => Object.fromEntries(Object.entries(limits || {}).flatMap(([method, values]) => {
  const clean = Object.fromEntries(Object.entries(values || {}).filter(([, value]) => Number(value) > 0).map(([key, value]) => [key, Number(value)]))
  return Object.keys(clean).length ? [[method, clean]] : []
}))
const saveProvider = async () => {
  if (!providerDraft.value.name.trim()) return showToast('请填写服务商名称', 'error')
  if (!providerDraft.value.supportedMethods.length) return showToast('请至少选择一种支付方式', 'error')
  const missing = providerFields.value.filter(field => !field.optional && !String(providerDraft.value.config[field.key] || '').trim())
  if (missing.length) return showToast(`请填写${missing[0].label}`, 'error')
  providerSaving.value = true
  try {
    const body = { ...toRaw(providerDraft.value), config:toRaw(providerDraft.value.config), limits:cleanProviderLimits(providerDraft.value.limits) }
    await api(providerDraft.value.id ? `/api/admin/payment/providers/${providerDraft.value.id}` : '/api/admin/payment/providers', { method:providerDraft.value.id ? 'PUT' : 'POST', body })
    providerDraft.value = null
    providers.value = await api('/api/admin/payment/providers')
    showToast('支付服务商保存成功', 'success')
  } finally { providerSaving.value = false }
}
const removeProvider = async provider => { if (!confirm(`删除 ${provider.name}？`)) return; await api(`/api/admin/payment/providers/${provider.id}`,{method:'DELETE'}); providers.value=await api('/api/admin/payment/providers'); showToast('支付服务商已删除', 'success') }
const editPlan = plan => { planDraft.value=plan?{...cloneData(plan),priceYuan:Number(plan.priceCents || 0)/100}:{name:'',description:'',priceYuan:1,cardCount:1,currency:'CNY',features:[],forSale:true,sortOrder:0} }
const savePlan = async () => { const priceYuan=Number(planDraft.value.priceYuan); if (!Number.isFinite(priceYuan) || priceYuan < 0.01) { showToast('套餐价格不能低于 0.01 元','error'); return } const body={...toRaw(planDraft.value),priceCents:Math.round(priceYuan*100)}; delete body.priceYuan; await api(planDraft.value.id?`/api/admin/payment/plans/${planDraft.value.id}`:'/api/admin/payment/plans',{method:planDraft.value.id?'PUT':'POST',body}); planDraft.value=null; plans.value=await api('/api/admin/payment/plans'); showToast('点歌券套餐保存成功','success') }
const removePlan = async plan => { if (!confirm(`删除 ${plan.name}？`)) return; await api(`/api/admin/payment/plans/${plan.id}`,{method:'DELETE'}); plans.value=await api('/api/admin/payment/plans') }
const verifyOrder = async order => { await api(`/api/admin/payment/orders/${order.id}/verify`,{method:'POST'}); await loadOrders() }
const openRefund = order => { refundDraft.value={id:order.id,amountCents:order.payAmountCents-order.refundAmountCents,reason:'管理员退款'} }
const refundOrder = async () => { await api(`/api/admin/payment/orders/${refundDraft.value.id}/refund`,{method:'POST',body:refundDraft.value}); refundDraft.value=null; await loadOrders() }
onMounted(async () => { siteOrigin.value = window.location.origin; await loadCore(); await ensureActiveTabLoaded(activeTab.value) })
</script>

